INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q6200334', 'Siege of Pelium', 'The siege of Pelium was undertaken by Alexander the Great against the Illyrian tribes in parts of what is modern-day Albania. It was critical for Alexander to take this pass as it provided easy access to Illyria and Macedonia, which was urgently needed in order to quell the unrest in Greece at this time in Athens and Thebes.', -335, 12, NULL, NULL, NULL, NULL, 'month', 'December 335 BCE', 55, 'https://en.wikipedia.org/wiki/Siege_of_Pelium'),
  ('Q16983812', 'Battle of Phoenice', 'The Battle of Phoenice took place in 230 BC between the forces of the Epirote League and the Ardiaean Kingdom of Illyria.', -230, NULL, NULL, NULL, NULL, NULL, 'year', '230 BCE', 34, 'https://en.wikipedia.org/wiki/Battle_of_Phoenice'),
  ('Q3233509', 'Battle of the Aous', 'The Battle of the Aous was fought in 198 BC between the Roman Republic and the Kingdom of Macedon, in the area between modern Tepelenë and Këlcyrë in Albania. The Roman forces were led by Titus Quinctius Flamininus and the Macedonian ones were led by Philip V. The Antigonid Macedonian army encamped behind a pass in an unassailable position.', -198, NULL, NULL, NULL, NULL, NULL, 'year', '198 BCE', 51, 'https://en.wikipedia.org/wiki/Battle_of_the_Aous_(198_BC)'),
  ('Q525325', 'Battle of Dyrrhachium', 'The Battle of Dyrrachium (or Dyrrhachium) took place from April to late July 48 BC near the city of Dyrrachium (modern-day Durrës) in what is now Albania. It was fought between Gaius Julius Caesar and an army led by Gnaeus Pompey during Caesar''s civil war.', -48, 7, 10, NULL, NULL, NULL, 'day', '10 July 48 BCE', 61, 'https://en.wikipedia.org/wiki/Battle_of_Dyrrhachium_(48_BC)'),
  ('Q3436319', 'Battle of Dyrrhachium', 'The Battle of Dyrrhachium in February 1018 was a part of the Byzantine–Bulgarian wars. It happened as the Bulgarian tsar Ivan Vladislav tried to establish his power on the southeastern coast of the Adriatic Sea.', 1018, 2, NULL, NULL, NULL, NULL, 'month', 'February 1018', 47, 'https://en.wikipedia.org/wiki/Battle_of_Dyrrhachium_(1018)'),
  ('Q1987213', 'Battle of Dyrrhachium', 'The Battle of Dyrrhachium took place on October 18, 1081 between the Byzantine Empire, led by the Emperor Alexios I Komnenos (r. 1081–1118), and the Normans of southern Italy under Robert Guiscard, Duke of Apulia and Calabria. The battle was fought outside the city of Dyrrhachium (present-day Durrës in Albania), the major Byzantine stronghold in the western Balkans, and ended in a Norman victory.', 1081, 10, 18, NULL, NULL, NULL, 'day', '18 October 1081', 65, 'https://en.wikipedia.org/wiki/Battle_of_Dyrrhachium_(1081)'),
  ('Q349318', 'Siege of Berat', 'The siege of Berat in Albania by the forces of the Angevin Kingdom of Sicily against the Byzantine garrison of the city took place in 1280–1281. Berat was a strategically important fortress, whose possession would allow the Angevins access to the heartlands of the Byzantine Empire.', 1280, NULL, NULL, 1281, NULL, NULL, 'year', '1280–1281', 41, 'https://en.wikipedia.org/wiki/Siege_of_Berat_(1280%E2%80%931281)'),
  ('Q2603935', 'Battle of Savra', 'The Battle of Savra (Albanian: Beteja e Savrës; Serbian: Bitka na Saurskom polju; Turkish: Savra Muharebesi; "Battle on the Saurian field") or the Battle of the Vjosë was fought on 18 September 1385 between Ottoman and much smaller Zetan forces, at the Savra field near Lushnjë (in modern-day southern Albania).', 1385, 9, 18, NULL, NULL, NULL, 'day', '18 September 1385', 56, 'https://en.wikipedia.org/wiki/Battle_of_Savra'),
  ('Q3183607', 'First Scutari War', 'The First Scutari War (Albanian: Lufta e Parë e Shkodrës; Serbo-Croatian: Први скадарски рат) was an armed conflict in 1405–1412 between Zeta and the Venetian Republic over Shkodër and other former possessions of Zeta captured by Venice.', 1405, NULL, NULL, 1413, 1, 30, 'year', '1405 – 30 January 1413', 34, 'https://en.wikipedia.org/wiki/First_Scutari_War'),
  ('Q60489', 'Albanian–Venetian War', 'The Albanian–Venetian War of 1447–48 (Albanian: Lufta Shqiptaro-Veneciane) was waged between Venetian and Ottoman forces against the Albanians under George Kastrioti Skanderbeg. The war was the result of a dispute between the Republic of Venice and the Dukagjini family over the possession of the Dagnum fortress.', 1447, 12, NULL, 1448, 10, 4, 'month', 'December 1447 – 4 October 1448', 53, 'https://en.wikipedia.org/wiki/Albanian%E2%80%93Venetian_War'),
  ('Q73670', 'Siege of Krujë', 'The first siege of Krujë (Albanian: Rrethimi i parë i Krujës) occurred in 1450 when an Ottoman army led by Sultan Murad II and his crown prince Mehmed II tried to besiege the Albanian town of Krujë. The League of Lezhë, led by Skanderbeg, experienced low morale after losing Svetigrad and Berat between 1448 and 1450.', 1450, 5, 14, 1450, 11, 23, 'day', '14 May 1450 – 23 November 1450', 51, 'https://en.wikipedia.org/wiki/Siege_of_Kruj%C3%AB_(1450)'),
  ('Q3300177', 'Siege of Berat', 'The siege of Berat (Albanian: Rrethimi i Beratit) took place in July 1455 when the Albanian army of Skanderbeg attempted to capture the fortress in the Albanian city of Berat, which was held by Ottoman forces. The attempt resulted in a failure when an Ottoman relief army arrived and routed the besieging forces.', 1455, 7, NULL, NULL, NULL, NULL, 'month', 'July 1455', 47, 'https://en.wikipedia.org/wiki/Siege_of_Berat_(1455)'),
  ('Q74072', 'Battle of Albulena', 'The Battle of Albulena (Albanian: Beteja e Albulenës), also known as the Battle of Ujëbardha, was fought on 2 September 1457 between Albanian forces led by Skanderbeg and an Ottoman army under Evrenosoğlu İsa Bey and Skanderbeg''s nephew, Hamza Kastrioti. Skanderbeg had been the leader of the Albanians for over a decade and had seen many victories over the Ottoman armies.', 1457, 9, 2, NULL, NULL, NULL, 'day', '2 September 1457', 52, 'https://en.wikipedia.org/wiki/Battle_of_Albulena'),
  ('Q960449', 'Siege of Krujë', 'The second siege of Krujë (Albanian: Rrethimi i dytë i Krujës) took place from June 1466 to 23 April 1467. Sultan Mehmed II of the Ottoman Empire led an army into Albania to defeat Skanderbeg, the leader of the League of Lezhë, which was created in 1444 after he began his war against the Ottomans.', 1467, 4, 23, 1467, 4, 23, 'day', '23 April 1467', 50, 'https://en.wikipedia.org/wiki/Siege_of_Kruj%C3%AB_(1466%E2%80%931467)'),
  ('Q2348233', 'Siege of Krujë', 'The 1467 Albanian campaign (Albanian: Fushata shqiptare e vitit 1467) by Mehmed II and the Ottoman Empire took place in the summer of 1467 in Albania. As a result of the campaign, the fortresses and regions of Albania were divided between Venice and the Ottomans.', 1467, NULL, NULL, NULL, NULL, NULL, 'year', '1467', 39, 'https://en.wikipedia.org/wiki/Mehmed_II''s_1467_Albanian_campaign'),
  ('Q7510401', 'Siege of Shkodra', 'The siege of Shkodra (Albanian: Rrethimi i Shkodrës) of 1474 was an Ottoman attack upon Venetian-controlled Shkodra (Venetian: Scutari) in Albania Veneta during the First Ottoman-Venetian War (1463–79). It is not to be confused with the siege of Shkodra of 1478–79.', 1474, 4, NULL, 1474, 8, 8, 'month', 'April 1474 – 8 August 1474', 41, 'https://en.wikipedia.org/wiki/Siege_of_Shkodra_(1474)'),
  ('Q2348220', 'Siege of Krujë', 'The fourth siege of Krujë (Ottoman Turkish: ‎آقچه حصار نك چهارم محاصره‌سى; Albanian: Rrethimi i katërt i Krujës) was an Ottoman siege of the Venetian-held fortress of Krujë in Albania from spring 1477 until 16 June 1478. Beginning in the spring of 1477, Ottoman forces under Evrenosoğlu Ahmed Bey blockaded the fortress and attempted to prevent supplies and reinforcements from reaching its garrison.', 1477, NULL, NULL, 1478, NULL, NULL, 'year', '1477–1478', 43, 'https://en.wikipedia.org/wiki/Siege_of_Kruj%C3%AB_(1477%E2%80%931478)'),
  ('Q7510403', 'Siege of Shkodra', 'The siege of Shkodra (Albanian: Rrethimi i Shkodrës) took place from May 1478 to April 1479 as a confrontation between the Ottoman Empire and the Venetians together with the League of Lezhë and other Albanians at Shkodra (Scutari in Italian) and its Rozafa Castle during the First Ottoman-Venetian War (1463–1479). Ottoman historian Franz Babinger called the siege "one of the most remarkable episodes in the struggle between the West and the Crescent".', 1478, 5, NULL, 1479, 4, 25, 'month', 'May 1478 – 25 April 1479', 43, 'https://en.wikipedia.org/wiki/Siege_of_Shkodra'),
  ('Q2309409', 'Morean War', 'The Morean war (Italian: Guerra di Morea), also known as the Sixth Ottoman–Venetian War, was fought between 1684–1699 as part of the wider conflict known as the "Great Turkish War", between the Republic of Venice and the Ottoman Empire. Military operations ranged from Dalmatia to the Aegean Sea, but the war''s major campaign was the Venetian conquest of the Morea (Peloponnese) peninsula in Southern Greece.', 1684, 4, 25, 1699, 1, 26, 'day', '25 April 1684 – 26 January 1699', 63, 'https://en.wikipedia.org/wiki/Morean_War'),
  ('Q1280245', 'Albanian revolt of 1912', 'The Albanian revolt of 1912 (Albanian: Kryengritja e vitit 1912, "Uprising of 1912") was the last revolt against the Ottoman Empire''s rule in Albania and lasted from January until August 1912. The revolt ended when the Ottoman government agreed to fulfill the rebels'' demands on 4 September 1912.', 1912, 1, NULL, 1912, 8, NULL, 'month', 'January 1912 – August 1912', 53, 'https://en.wikipedia.org/wiki/Albanian_revolt_of_1912'),
  ('Q2149254', 'Siege of Scutari', 'The siege of Scutari, also referred to as the siege of Shkodër (Albanian: Rrethimi i Shkodrës, Serbian: Опсада Скадра), known in Turkish as İşkodra Müdafaası (in Turkish) or İşkodra Savunması , took place from 28 October 1912 to 23 April 1913 when the army of the Kingdom of Montenegro defeated the forces of the Ottoman Empire and captured Shkodër.', 1912, 10, 28, 1913, 4, 23, 'day', '28 October 1912 – 23 April 1913', 56, 'https://en.wikipedia.org/wiki/Siege_of_Scutari_(1912%E2%80%931913)'),
  ('Q5037029', 'Capture of Korytsa', 'The Capture of Korytsa by the Hellenic armed forces, happened on 20 December 1912, during the First Balkan War.', 1912, 12, 20, NULL, NULL, NULL, 'day', '20 December 1912', 41, 'https://en.wikipedia.org/wiki/Capture_of_Korytsa'),
  ('Q23020293', 'Battle of Lumë', 'The Battle of Lumë (Albanian: Beteja e Lumës, Serbian Cyrillic: Битка у Љуми) was a series of clashes during the First Balkan War between Albanian local forces and the army of the Kingdom of Serbia. The conflict took place between 15 November and 5 December 1912 in the Lumë.', 1912, 12, 6, NULL, NULL, NULL, 'day', '6 December 1912', 39, 'https://en.wikipedia.org/wiki/Battle_of_Lum%C3%AB'),
  ('Q838704', 'Battle of Durazzo', 'The First Battle of Durazzo was a naval battle of World War I. It was fought off Durazzo (now Durrës), Albania at the end of December 1915 and involved the navies of Austria-Hungary, the United Kingdom, the Kingdom of Italy, and France.', 1915, 12, 29, 1915, 12, 29, 'day', '29 December 1915', 41, 'https://en.wikipedia.org/wiki/Battle_of_Durazzo_(1915)'),
  ('Q3636419', 'Battle of Durazzo', 'The Second Battle of Durazzo, or the Bombardment of Durazzo was a naval battle fought in the Adriatic Sea during the First World War. A large allied fleet led by the Regia Marina attacked the enemy-held port at Durazzo, Albania.', 1918, 10, 2, NULL, NULL, NULL, 'day', '2 October 1918', 34, 'https://en.wikipedia.org/wiki/Battle_of_Durazzo_(1918)'),
  ('Q714644', 'Italian invasion of Albania', 'The Italian invasion of Albania was a brief military campaign which was launched by Italy against Albania in 1939. The conflict was a result of the imperialistic policies of the Italian prime minister and dictator Benito Mussolini.', 1939, NULL, NULL, 1939, 4, 12, 'year', '1939', 70, 'https://en.wikipedia.org/wiki/Italian_invasion_of_Albania'),
  ('Q48779976', 'Battle of Durrës', 'The Battle of Durrës was one of the main confrontations during the April 1939 Italian invasion of Albania. It took place on 7 April, the first day of the invasion, between the Italian invaders and the Albanian defenders and resulted in an Italian victory.', 1939, 4, 7, NULL, NULL, NULL, 'day', '7 April 1939', 34, 'https://en.wikipedia.org/wiki/Battle_of_Durr%C3%ABs_(1939)'),
  ('Q162362', 'World War II in the Balkans', 'The Balkans campaign of World War II began with the Italian invasion of Greece on 28 October 1940. In the early months of 1941, Italy''s offensive had stalled and a Greek counter-offensive pushed into Albania.', 1940, 10, 28, 1941, 6, 1, 'day', '28 October 1940 – 1 June 1941', 70, 'https://en.wikipedia.org/wiki/Balkans_campaign_(World_War_II)'),
  ('Q4871234', 'Battle of Himara', 'The Battle of Himara (Greek: Η Μάχη της Χειμάρρας) was a military conflict that took place in the Greco-Italian War in December 1940, during the counteroffensive of the Greek Army that followed the failed Italian invasion of Greece. After the Greek victory in Himara, the Italian dictator Benito Mussolini, admitted that one of the causes of the Italian defeat was the high morale of the Greek troops.', 1940, 12, 13, 1940, 12, 22, 'day', '13 December 1940 – 22 December 1940', 34, 'https://en.wikipedia.org/wiki/Battle_of_Himara'),
  ('Q6784477', 'Massacre of Borovë', 'The Borovë massacre occurred on July 6, 1943, in the village of Borovë, during the Second World War in southeastern Albania. German forces killed 107 civilians as a reprisal for a Partisan attack on a German convoy in the village of Barmash.', 1943, 7, 9, NULL, NULL, NULL, 'day', '9 July 1943', 39, 'https://en.wikipedia.org/wiki/Borov%C3%AB_massacre'),
  ('Q6784476', '1951 executions in Albania', 'The People''s Republic of Albania executed 22 intellectuals without trial on 26 February 1951, as ordered by Enver Hoxha. They were accused of bombing the Soviet embassy in Tirana.', 1951, 2, 26, NULL, NULL, NULL, 'day', '26 February 1951', 39, 'https://en.wikipedia.org/wiki/1951_executions_in_Albania'),
  ('Q3454834', 'Albanian monarchy referendum, 1997', 'A referendum on restoring the monarchy was held in Albania on 29 June 1997 alongside parliamentary elections. The proposal was rejected by 66.7% of voters.', 1997, 6, 29, NULL, NULL, NULL, 'day', '29 June 1997', 43, 'https://en.wikipedia.org/wiki/1997_Albanian_monarchy_referendum'),
  ('Q190029', 'Kosovo War', 'The Kosovo War (Albanian: Lufta e Kosovës; Serbian: Косовски рат, Kosovski rat) was an armed conflict in Kosovo that lasted from 28 February 1998 until 11 June 1999. It was fought between the forces of the Federal Republic of Yugoslavia (FRY), which controlled Kosovo before the war, and the Kosovo Albanian separatist militia known as the Kosovo Liberation Army (KLA).', 1998, 2, NULL, 1999, 6, 11, 'month', 'February 1998 – 11 June 1999', 81, 'https://en.wikipedia.org/wiki/Kosovo_War'),
  ('Q3303959', 'Battle of Koshare', 'The Battle of Košare (Serbian: Битка на Кошарама, romanized: Bitka na Košarama; Albanian: Beteja e Kosharës) was fought during the Kosovo War between the forces of FR Yugoslavia and the Kosovo Liberation Army (KLA), the latter supported by the NATO air forces and Albanian Army. The battle was fought around Košare on the border between FR Yugoslavia and Albania from 9 April 1999 until 10 June 1999 during the NATO bombing of FR Yugoslavia.', 1999, 4, 9, 1999, 6, 10, 'day', '9 April 1999 – 10 June 1999', 48, 'https://en.wikipedia.org/wiki/Battle_of_Ko%C5%A1are'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q2457479', '2011 Albanian opposition demonstrations', 'Anti-government protests took place in 2011 in cities across Albania following 18 months of political conflict over alleged electoral fraud by the opposition. A video surfaced which portrayed the deputy prime minister arranging a corrupt deal with the minister of economy.', 2013, NULL, NULL, NULL, NULL, NULL, 'year', '2013', 47, 'https://en.wikipedia.org/wiki/2011_Albanian_opposition_demonstrations'),
  ('Q63078193', 'Regional Roaming Agreement', 'The Regional Roaming Agreement, formally the Agreement on the price reduction of the roaming services in public mobile communications networks in the Western Balkans region, regulates the imposition of roaming charges within the countries in the Western Balkans; Albania, Kosovo, Bosnia and Herzegovina, North Macedonia, Montenegro and Serbia. The agreement covers both the charges mobile network operators can impose on their subscribers for using telephone and data services outside of the network''s member state, and the wholesale rates networks can charge each other to allow their subscribers…', 2019, 4, 4, NULL, NULL, NULL, 'day', '4 April 2019', 41, 'https://en.wikipedia.org/wiki/Regional_Roaming_Agreement'),
  ('Q76529995', '2019 Albania earthquake', 'On 26 November 2019 at 03:54 CET (UTC+1), northwestern Albania was struck by a magnitude 6.4 earthquake with an epicentre 16 kilometres (9.9 mi) west-southwest of Mamurras. The earthquake lasted at least 50 seconds and was felt in Albania''s capital Tirana, and in places as far away as Bari, Taranto and Belgrade, 370 kilometres (230 mi) northeast of the epicentre.', 2019, 11, 26, NULL, NULL, NULL, 'day', '26 November 2019', 65, 'https://en.wikipedia.org/wiki/2019_Albania_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q139998119', 'Flamingo Revolution', 'The Flamingo Revolution (Albanian: Revolucioni i Flamingove) is a decentralised social movement and series of protests primarily against the Government of Albania. The initial protests took place in Baks-Rrjoll on 2 February 2026 when residents protested against the planned Blue Borgo resort and disputed land ownership.', 2026, 5, 23, NULL, NULL, NULL, 'day', '23 May 2026', 63, 'https://en.wikipedia.org/wiki/Flamingo_Revolution');
